/**
 * healthFacilitiesData.ts — routing + registry data for the health-facilities
 * hub (epic #4455 / sub #4457).
 *
 * Imported by:
 *   - build-plugins/searchConsoleCompat.ts   (self-map — SPA-safe: no fs)
 *   - build-plugins/healthFacilitiesJobsAggregate.ts
 *   - build-plugins/healthFacilitiesPlugin.ts
 *   - build-plugins/healthFacilitiesLinksPlugin.ts
 *
 * The committed registry `data/health-facilities-jobs.json` (generated by
 * scripts/generate-health-facilities-jobs.mjs) is the STABLE universe: every
 * facility here gets, on every build, EITHER a full indexable page (live job
 * count ≥ floor) OR a noindex,follow below-floor bridge — always at the SAME
 * canonical path. So every path enumerated here is guaranteed to have a live
 * target, which is exactly the invariant the searchConsoleCompat self-map
 * relies on (mirrors professionCantonData's isProfessionCantonPath).
 *
 * A static JSON import is safe here (the registry is ~85 KB, not the 150 MB
 * jobs.json the loadJobsJson guard warns about) — same pattern as
 * searchConsoleCompat's `canton-url-slugs.json` import.
 */

import registryFile from '../data/health-facilities-jobs.json';
import type { HealthFacilityCategory } from './healthFacilitiesMatch';

export type HealthFacilityLocale = 'it' | 'en' | 'de' | 'fr';

export const HEALTH_FACILITY_LOCALES: readonly HealthFacilityLocale[] = ['it', 'en', 'de', 'fr'];

/** Locale → URL section (no leading/trailing slash). */
export const HEALTH_FACILITY_SECTION: Record<HealthFacilityLocale, string> = {
  it: 'strutture-sanitarie',
  en: 'en/healthcare-facilities',
  de: 'de/gesundheitseinrichtungen',
  fr: 'fr/etablissements-sante',
};

/** Locale → the hub root path (index of all facilities is NOT emitted; this is
 * used only for breadcrumbs / hreflang of the section). */
export function buildHealthFacilitySectionPath(locale: HealthFacilityLocale): string {
  return `/${HEALTH_FACILITY_SECTION[locale]}/`.replace(/\/{2,}/g, '/');
}

/** Canonical path for a single facility in the target locale (trailing slash). */
export function buildHealthFacilityPath(locale: HealthFacilityLocale, slug: string): string {
  return `/${HEALTH_FACILITY_SECTION[locale]}/${slug}/`.replace(/\/{2,}/g, '/');
}

/** One committed facility record (subset of the registry shape the build reads). */
export interface HealthFacilityRecord {
  readonly slug: string;
  readonly companyKeys: readonly string[];
  readonly name: string;
  readonly canton: string;
  readonly city: string;
  readonly category: HealthFacilityCategory;
  readonly matchType: 'employer' | 'geo';
  readonly sites: readonly string[];
  readonly commuterOrigins: readonly string[];
  readonly jobCountSnapshot: number;
  readonly healthcareJobCountSnapshot: number;
  readonly healthcareRoleCountsSnapshot: Readonly<Record<string, number>>;
  readonly medianSalaryChfSnapshot: number | null;
  readonly aboveFloorSnapshot: boolean;
}

interface HealthFacilitiesRegistry {
  readonly generatedAt: string;
  readonly minJobsFloor: number;
  readonly facilities: readonly HealthFacilityRecord[];
}

const registry = registryFile as unknown as HealthFacilitiesRegistry;

/** Job-count floor below which a facility renders a noindex bridge, not a page. */
export const HEALTH_FACILITY_MIN_JOBS: number = registry.minJobsFloor ?? 3;

/** All committed facility records, sorted by snapshot job count (desc). */
export const HEALTH_FACILITIES: readonly HealthFacilityRecord[] = registry.facilities ?? [];

/** slug → record. */
const RECORD_BY_SLUG: ReadonlyMap<string, HealthFacilityRecord> = new Map(
  HEALTH_FACILITIES.map((f) => [f.slug, f]),
);

export function getHealthFacility(slug: string): HealthFacilityRecord | undefined {
  return RECORD_BY_SLUG.get(slug);
}

/** Every (locale × facility) canonical path. */
export function listHealthFacilityPaths(): string[] {
  const out: string[] = [];
  for (const f of HEALTH_FACILITIES) {
    for (const locale of HEALTH_FACILITY_LOCALES) out.push(buildHealthFacilityPath(locale, f.slug));
  }
  return out;
}

// Precomputed O(1) path index — built ONCE at module load (never a per-call
// resolver inside searchConsoleCompat's 150k+-path loop; same rationale as
// professionCantonData's PATH_INDEX / the SELF_MAPPABLE_* Sets).
const PATH_INDEX: ReadonlySet<string> = new Set(listHealthFacilityPaths());

function normalizePath(urlPath: string): string {
  const p = String(urlPath || '').split('?')[0].split('#')[0];
  return p.endsWith('/') ? p : `${p}/`;
}

/** True when the path is one of the enumerated facility canonical paths. */
export function isHealthFacilityPath(urlPath: string): boolean {
  return PATH_INDEX.has(normalizePath(urlPath));
}

export interface HealthFacilityRoutePath {
  locale: HealthFacilityLocale;
  slug: string;
}

// Parsed twin of PATH_INDEX — services/router.ts needs the locale (isHealthFacilityPath
// is boolean-only), mirroring exchangeSsgPaths.ts's isX/parseX shape.
const PARSED_PATH_INDEX: ReadonlyMap<string, HealthFacilityRoutePath> = new Map(
  HEALTH_FACILITIES.flatMap((f) =>
    HEALTH_FACILITY_LOCALES.map((locale) => [buildHealthFacilityPath(locale, f.slug), { locale, slug: f.slug }] as const),
  ),
);

/** Parses a facility canonical path into its locale + slug, or null if unmatched. */
export function parseHealthFacilityPath(urlPath: string): HealthFacilityRoutePath | null {
  return PARSED_PATH_INDEX.get(normalizePath(urlPath)) ?? null;
}
